function mkSim(main,c){const pl=c.plots||[],ev=c.ev||{};
  main.innerHTML=`<h2>${c.h2}</h2><p class="lead">${c.lead}</p>
  <div class="card" style="padding:10px"><div class="btns"><select id="zPre" style="width:auto;max-width:100%"></select>${Object.entries(ev).map(([k,v])=>`<button class="b" data-ev="${k}">${v.l}</button>`).join("")}${c.step?`<button class="b" id="zPl">⏸︎ Пауза</button>`:""}</div>
   <div class="zscroll" style="overflow-x:auto;-webkit-overflow-scrolling:touch"><canvas id="zC" style="width:100%;min-width:540px;height:${c.ch||340}px;display:block;margin-top:6px"></canvas></div><div class="zhint">↔ плъзни схемата настрани</div>
   <div class="stats" id="zS" style="margin-top:8px"></div>
   <div class="note" id="zN" style="min-height:4.2em"></div>${c.note?`<div class="note" id="zD" style="min-height:3em"></div>`:""}
   <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px">${pl.map((p,i)=>`<canvas class="plot" id="zP${i}" style="height:${p.h||210}px"></canvas>`).join("")}</div>
   ${c.legend?`<div class="legend">${c.legend}</div>`:""}
   <div class="grid2 zsl" style="grid-template-columns:1fr 1fr"><div id="zc1"></div><div id="zc2"></div></div></div>
  ${c.after||""}<h3>Експерименти</h3><div id="ex"></div>`;
  const sel=$("#zPre"),S={};let R=null,s=null,hist=[],t=0,play=1,fr=0,cur=Object.keys(c.pre)[0];
  sel.innerHTML=Object.entries(c.pre).map(([k,v])=>`<option value="${k}">${v.n}</option>`).join("");
  const P=()=>{const o={pre:cur};c.sl.forEach(d=>o[d.k]=S[d.k].get());return o};
  function stats(){const p=P();$("#zS").innerHTML=statsHTML(c.stats(p,R,s,t));if(c.note){const h=c.note(p,R,s,t),n=$("#zD");if(n.__h!==h){n.__h=h;n.innerHTML=h;linkTerms(n)}}pl.forEach((q,i)=>plot($("#zP"+i),q.f(p,R,hist,s,t)))}
  const upd=()=>{R=c.calc(P(),s,t);stats()};
  c.sl.forEach((d,i)=>{S[d.k]=slider($(i<Math.ceil(c.sl.length/2)?"#zc1":"#zc2"),d,()=>{if(!c.step)upd()})});
  const setPre=(k,o={})=>{cur=k;const v=c.pre[k];sel.value=k;c.sl.forEach(d=>S[d.k].set(d.value));Object.entries(Object.assign({},v.set,o.sl)).forEach(([a,b])=>S[a]&&S[a].set(b));
    $("#zN").innerHTML=v.info||"";linkTerms($("#zN"));if(c.init){s=c.init(P());hist=[];t=0}const e=o.ev||v.ev;if(e&&ev[e])ev[e].f(s,P(),t);upd()};
  sel.onchange=()=>setPre(sel.value);
  main.querySelectorAll("[data-ev]").forEach(b=>b.onclick=()=>{ev[b.dataset.ev].f(s,P(),t);if(!c.step)upd()});
  if(c.step)$("#zPl").onclick=()=>{play^=1;$("#zPl").textContent=play?"⏸︎ Пауза":"▶︎ Пусни"};
  setPre(cur);
  experiments($("#ex"),c.exp,c.key,e=>{setPre(e.pre||Object.keys(c.pre)[0],e);$("#zC").scrollIntoView({behavior:"smooth",block:"center"})});
  rLoop($("#zC"),dt=>{const p=P();if(c.step&&play){const D=dt*(c.speed||1),n=Math.max(1,Math.ceil(D/(c.dtmax||0.05)));for(let i=0;i<n;i++)c.step(s,p,D/n,t+D*i/n);t+=D;
      if(c.rec&&(!hist.length||t-hist[hist.length-1][0]>=(c.recdt||0))){hist.push(c.rec(s,p,t));if(hist.length>(c.hmax||700))hist.shift()}R=c.calc(p,s,t)}else if(!c.step)t+=dt;
    const cv=rcv($("#zC"));if(cv){const {g,W,H}=cv,cw=c.cw||640,ch=c.ch||340,k=Math.min(W/cw,H/ch);g.save();g.translate((W-cw*k)/2,(H-ch*k)/2);g.scale(k,k);c.draw(g,p,R,t,dt,s);g.restore()}
    if(c.step&&++fr%8===0)stats()});
  window.onresize=()=>stats()}
