const ARC={top:2.5,y:2.68};
function zTubeM(T,pts,mat,r=0.17,seg=80){return new T.Mesh(new T.TubeGeometry(new T.CatmullRomCurve3(pts.map(p=>new T.Vector3(p[0],p[1],p[2]||0)),false,"catmullrom",0.25),seg,r,8),mat)}
function zCordSeg(T,g,o={}){const h=5,top=ARC.top,sh=pts=>{const c=new T.CatmullRomCurve3(pts.map(p=>new T.Vector3(p[0],p[1],0)),true,"catmullrom",0.5).getPoints(140);return new T.Shape(c.map(v=>new T.Vector2(v.x,v.y)))},ex=(s,d,m)=>{const q=new T.ExtrudeGeometry(s,{depth:d,bevelEnabled:false,curveSegments:24});q.rotateX(-Math.PI/2);q.translate(0,-top,0);const me=new T.Mesh(q,m);g.add(me);return me};
  const half=[[0,-0.9],[1.0,-1.1],[1.6,-2.6],[2.3,-3.5],[3.5,-3.3],[3.9,-2.2],[3.5,-0.9],...(o.lat?[[4.3,-0.2]]:[]),[3.2,0.6],[2.6,1.7],[2.9,3.0],[2.5,3.9],[1.9,3.6],[1.5,2.0],[1.0,0.9],[0,0.8]],grey=half.concat(half.slice(1,-1).reverse().map(p=>[-p[0],p[1]]));
  const wp=[];for(let k=0;k<40;k++){const a=k/40*6.283,nx=Math.cos(a),ny=Math.sin(a);wp.push([6*nx*(1-0.05*Math.max(0,-ny)),4.7*ny+(Math.abs(nx)<0.12&&ny<0?0.9:0)])}
  ex(sh(wp),h,new T.MeshPhysicalMaterial({color:LIN(T,0xf7ecd2),transparent:true,opacity:0.72,roughness:0.5,depthWrite:false,side:T.DoubleSide}));ex(sh(grey),h+0.08,MK.mat(T,0x8f6f72,{roughness:0.8,clearcoat:0}));
  const cc=new T.Mesh(new T.CylinderGeometry(0.2,0.2,0.1,12),MK.mat(T,0x5c4a4a));cc.position.set(0,top+0.1,0);g.add(cc);
  const sm=new T.MeshPhysicalMaterial({color:LIN(T,0xf1e3c4),transparent:true,opacity:0.3,roughness:0.5,depthWrite:false}),gm=new T.MeshPhysicalMaterial({color:LIN(T,0xe9c46a),transparent:true,opacity:0.45,roughness:0.4,depthWrite:false});
  (o.sides||[1]).forEach(s=>{const P=arcP(s);g.add(zTubeM(T,[[2.4*s,2.3,-3.9],P.DR1,P.DRG,P.SN],sm,0.75,40));g.add(zTubeM(T,[[2.9*s,2.3,3.7],P.VR1,P.VR2,P.SN],sm,0.75,40));g.add(zTubeM(T,[P.SN,P.SN2,P.SN3],sm,1.0,30));const d=new T.Mesh(new T.SphereGeometry(1,20,14),gm);d.scale.set(1.9,1.25,1.35);d.position.set(P.DRG[0],P.DRG[1],P.DRG[2]);g.add(d)})}
function arcP(s){const y=ARC.y;return {s,DH:[2.3*s,y,-3.3],DHi:[2.1*s,y,-1.9],MID:[2.3*s,y,-0.3],LH:[3.7*s,y,0.15],VA:[2.9*s,y,2.6],VB:[1.9*s,y,3.0],VX:[3.0*s,2.35,3.8],DR1:[6*s,2.2,-5],DRG:[10.5*s,2.0,-3.6],SN:[13*s,1.7,-1.2],SN2:[17*s,1.0,0],SN3:[21*s,-0.5,2],VR1:[7*s,2.1,3.4],VR2:[11*s,1.9,1]}}
const arcAff=(P,rec,end)=>[rec,P.SN3,P.SN2,P.SN,P.DRG,P.DR1,P.DH,...end],arcEff=(P,soma,tgt)=>[soma,P.VX,P.VR1,P.VR2,P.SN,P.SN2,P.SN3,...tgt];
function zNrn(T,C,key,pts,col,o={}){const m=new T.MeshStandardMaterial({color:LIN(T,col),emissive:LIN(T,col),emissiveIntensity:0.15,roughness:0.5,transparent:true,opacity:1}),G=new T.Group();G.add(zTubeM(T,pts,m,o.r||0.17));
  if(o.soma){const s=new T.Mesh(new T.SphereGeometry(o.sr||0.55,16,12),m);s.position.set(o.soma[0],o.soma[1],o.soma[2]);G.add(s)}const e=pts[pts.length-1],b=new T.Mesh(new T.SphereGeometry(o.br||0.3,10,8),m);b.position.set(e[0],e[1],e[2]);G.add(b);C.g.add(G);(C.N=C.N||{})[key]={G,m,pts}}
function zNSet(C,key,v,act=0){const n=C.N[key];n.G.visible=v>0.02;n.m.opacity=Math.min(1,v);n.m.emissiveIntensity=0.08+0.75*act}
function zMuscle(T,C,key,pos,len,r,col){const g=new T.Group();g.position.set(pos[0],pos[1],pos[2]);const f=zFibre(T,len,r,col);f.rotation.z=Math.PI/2;g.add(f);const tm=MK.mat(T,0xefe6d2,{roughness:0.6});[1,-1].forEach(s=>{const t=new T.Mesh(new T.CylinderGeometry(r*0.28,r*0.5,2.6,10),tm);t.position.y=s*(len/2+1.2);if(s<0)t.rotation.z=Math.PI;g.add(t)});C.g.add(g);(C.M=C.M||{})[key]={g,f,pos,len}}
function zMusSet(C,key,L,glow=0){const m=C.M[key];m.f.scale.set(L,1/Math.sqrt(L),1/Math.sqrt(L));m.f.material.emissiveIntensity=glow}
