const MYO_K=[[0,-90],[0.1,-90],[0.125,25],[0.16,20],[0.22,8],[0.32,4],[0.6,-8],[0.78,-88],[1,-90]],myoV=p=>{for(let k=0;k<MYO_K.length-1;k++){const a=MYO_K[k],b=MYO_K[k+1];if(p<=b[0]){const w=(p-a[0])/(b[0]-a[0]);return a[1]+(b[1]-a[1])*(0.5-0.5*Math.cos(Math.PI*w))}}return -90};
const MYO_PATH=(()=>{let d="";for(let k=0;k<=100;k++){const p=k/100;d+=(k?"L":"M")+(6+p*158).toFixed(1)+" "+(14+(25-myoV(p))/115*46).toFixed(1)}return d})(),MYO_R=[[0,0.1],[0.1,0.16],[0.16,0.22],[0.22,0.6],[0.6,0.78],[0.78,1]];
