const STG_GFILT=zCellStg({id:"stgGF",title:"Как се филтрира кръвта: трите слоя на гломерулния филтър",
 intro:"Парче от стената на гломерулен капиляр, увеличено милион пъти. Горе е кръвта, долу — пространството на Боуман. Течността минава през три последователни сита; виж кое какво спира и какви сили я движат.",
 legend:[["#74c0fc","вода"],["#fab005","Na⁺"],["#f08c00","глюкоза"],["#b197fc","урея"],["#f2c94c","албумин (−)"],["#e03131","еритроцит"]],
 mechs:[{key:"g",label:"Филтър",center:"",cam:[0,2,0,50,0.3,1.2],foc:[[0,2,40],[0,5,28],[0,2.4,24,1.5],[0,0,24,1.95],[0,2,40],[0,2,40],[0,1,32,1.6]],stages:[
   {t:"Три слоя между кръвта и първичната урина",short:"Трите слоя",badge:"ендотел · базална мембрана · подоцити",d:"Гломерулният капиляр е покрит отвън с <b>подоцити</b>. Филтратът минава през три слоя: ендотела с прозорчета, <b>базалната мембрана</b> и процепите между израстъците на подоцитите. Заедно те пропускат водата и малките молекули стотици пъти по-лесно от обикновен капиляр, но задържат белтъците."},
   {t:"Слой 1: ендотел с прозорчета — спира клетките",short:"Ендотел: фенестри",badge:"пори 70–100 nm",d:"Ендотелът е надупчен с хиляди <b>фенестри</b>. Те са достатъчно големи за всички разтворени вещества, включително белтъците, но не и за <b>кръвните клетки</b>. Отрицателният заряд по повърхността му вече започва да отблъсква белтъците."},
   {t:"Слой 2: базална мембрана — отблъсква албумина",short:"Базална мембрана",badge:"мрежа с отрицателен заряд",d:"Гъста мрежа от колаген тип IV и <b>протеогликани с отрицателен заряд</b>. Албуминът е малко под границата по размер (≈ 6 nm срещу пори ≈ 8 nm), но също е отрицателен — отблъсква се. Затова през филтъра минава под 1 % от него."},
   {t:"Слой 3: процепи между израстъците на подоцитите",short:"Подоцити: процепна диафрагма",badge:"нефрин",d:"Израстъците на съседни подоцити се зацепват като пръсти. Между тях остават <b>филтрационни процепи</b>, преградени от тънка <b>процепна диафрагма</b> от белтъка нефрин — последното и най-фино сито. Водата, йоните, глюкозата, аминокиселините и уреята минават свободно."},
   {t:"Какво движи филтрацията: трите налягания",short:"Налягания",badge:"нетно ≈ +10 mmHg",d:"<b>Хидростатичното налягане в капиляра</b> (≈ 60 mmHg) изтласква течността. Срещу него действат <b>налягането в капсулата на Боуман</b> (≈ 18) и <b>онкотичното налягане на плазмата</b> (≈ 32), което расте по дължината на капиляра, защото белтъците остават. Нетното филтрационно налягане е само около 10 mmHg, но филтърът е толкова пропусклив, че се получават <b>125 mL/min</b> — 180 литра на ден, около 20 % от плазмата, която минава."},
   {t:"Регулация: двата „крана“ преди и след гломерула",short:"Аферентна и еферентна артериола",badge:"авторегулация",d:"<b>Свиване на аферентната артериола</b> понижава налягането в гломерула — филтрацията пада (симпатикус, аденозин при тубулогломерулната обратна връзка). <b>Свиване на еферентната артериола</b> го повишава — филтрацията се запазва при ниско кръвно налягане (ангиотензин II). Затова АСЕ-инхибиторите могат да понижат филтрацията при стеснена бъбречна артерия."},
   {t:"Когато филтърът се повреди: белтък в урината",short:"Протеинурия",badge:"нефротичен синдром",d:"Ако базалната мембрана загуби отрицателния си заряд или израстъците на подоцитите се слеят и процепната диафрагма се разруши, <b>албуминът преминава</b>. Губят се над 3,5 g белтък на ден, онкотичното налягане на плазмата пада и се появяват отоци — нефротичен синдром. При възпаление (гломерулонефрит) минават и еритроцити."}],
   spec:{cyto:[],mem:[],it:[],pools:{w:[0x74c0fc,0.16,150,"sph","вода"],na:[0xfab005,0.2,40],glu:[0xf08c00,0.3,30],ure:[0xb197fc,0.24,20],alb:[0xf2c94c,0.72,20]}},
   init(G,T,C){const g=C.g,sh=new T.Shape();sh.moveTo(-18,-6);sh.lineTo(18,-6);sh.lineTo(18,6);sh.lineTo(-18,6);sh.closePath();GF.holes.length=0;for(let a=-16.2;a<=16.3;a+=2.7)for(let b=-4.05;b<=4.1;b+=2.7){const h=new T.Path();h.absellipse(a,b,0.82,0.82,0,6.283);sh.holes.push(h);GF.holes.push([a,b])}
    const eg=new T.ExtrudeGeometry(sh,{depth:0.55,bevelEnabled:true,bevelSize:0.08,bevelThickness:0.08,bevelSegments:2,curveSegments:14});eg.rotateX(Math.PI/2);const en=new T.Mesh(eg,MK.mat(T,0xf08c8c,{roughness:0.45,clearcoat:0.4}));en.position.y=4.9;g.add(en);
    C.gbm=new T.Mesh(new T.BoxGeometry(36,1.7,12),new T.MeshPhysicalMaterial({color:LIN(T,0x9a8fd1),transparent:true,opacity:0.42,roughness:0.6,depthWrite:false}));C.gbm.position.y=2.6;g.add(C.gbm);
    const R=MK.rnd(5),cm=new T.MeshBasicMaterial({color:0x1c7ed6,transparent:true}),cim=new T.InstancedMesh(new T.BoxGeometry(0.5,0.12,0.12),cm,70),M=new T.Matrix4();for(let k=0;k<70;k++){M.makeTranslation(-17+R()*34,1.9+R()*1.4,k<26?6.06:-5.6+R()*11.4);cim.setMatrixAt(k,M)}g.add(cim);C.chg=cim;C.cm=cm;
    C.fp=[];GF.slits.length=0;const m1=MK.mat(T,0x38d9a9,{roughness:0.4,clearcoat:0.5}),m2=MK.mat(T,0x4dabf7,{roughness:0.4,clearcoat:0.5});for(let k=0;k<18;k++){const x=-16.6+k*1.95,f=new T.Group(),c=new T.Mesh(new T.CylinderGeometry(0.78,0.78,10.6,16),k%2?m2:m1);c.rotation.x=Math.PI/2;f.add(c);const e=new T.Mesh(new T.SphereGeometry(0.78,16,12),k%2?m2:m1);e.position.z=k%2?-5.3:5.3;f.add(e);f.position.set(x,0.75,k%2?0.5:-0.5);g.add(f);C.fp.push(f);if(k)GF.slits.push(x-0.975)}
    const bar=(z,m)=>{const b=new T.Mesh(new T.BoxGeometry(36.4,1.5,1.6),m);b.position.set(0,0.7,z);g.add(b)};bar(-6.6,m1);
    C.sd=new T.InstancedMesh(new T.BoxGeometry(0.42,0.07,10),new T.MeshPhysicalMaterial({color:LIN(T,0xffe066),transparent:true,opacity:0.75}),GF.slits.length);GF.slits.forEach((x,k)=>{M.makeTranslation(x,0.35,0);C.sd.setMatrixAt(k,M)});g.add(C.sd);
    C.rbc=[];const rm=MK.mat(T,0xc92a2a,{roughness:0.35,clearcoat:0.5});for(let k=0;k<4;k++){const r=new T.Mesh(new T.SphereGeometry(1,24,16),rm);r.scale.set(2.2,0.7,2.2);g.add(r);C.rbc.push(r)}},
   upd(C,i,u,t,sg,R){const dmg=i===6?sg(0.1,0.5):0,reg=i===5?(u<0.33?0:u<0.66?1:2):-1,pgc=reg===1?66:reg===2?49:60,net=pgc-18-32,flow=i===4||i===5?Z.cl(net/10,0,1.7):1;
    C.rbc.forEach((r,k)=>{r.position.set(((t*1.6+k*11)%44)-22,8.2+0.5*Math.sin(t+k*2),-3+k*2);r.rotation.z=0.3*Math.sin(t*0.7+k);r.rotation.x=0.4*Math.cos(t*0.5+k)});
    C.cm.opacity=1-0.9*dmg;C.gbm.material.opacity=0.42-0.2*dmg;C.fp.forEach((f,k)=>{f.scale.set(1+0.18*dmg,1-0.35*dmg,1)});C.sd.visible=dmg<0.5;
    const col=(pool,n,k0,ph,j)=>{for(let q=0;q<8;q++){const h=GF.holes[(q*7+k0*3)%GF.holes.length],sx=GF.slits.reduce((a,b)=>Math.abs(b-h[0])<Math.abs(a-h[0])?b:a,GF.slits[0]);R(pool,[[h[0],10.5,h[1]],[h[0],4.6,h[1]],[sx,2.4,h[1]],[sx,0.3,h[1]],[sx+(q%2?0.6:-0.6),-5.5,h[1]]],Math.max(0,Math.round(n*flow/8)),t*ph+q*0.13,j)}};
    col("w",110,0,0.3,0.14);col("na",28,1,0.28,0.12);col("glu",14,2,0.24,0.1);col("ure",12,3,0.26,0.1);
    for(let k=0;k<9;k++){const h=GF.holes[(k*5+2)%GF.holes.length],a=(t*0.16+k/9)%1,pass=dmg>0.5&&k%3===0;let y,x=h[0];if(pass){const sx=GF.slits.reduce((p,b)=>Math.abs(b-h[0])<Math.abs(p-h[0])?b:p,GF.slits[0]);y=10-15.5*a;x=a>0.4?sx:h[0]}else{y=a<0.5?10-13.2*a:3.4+13.2*(a-0.5);x=h[0]+(a>0.5?0:0)}C.L.alb.push({x,y:Math.max(pass?-6:3.5,y),z:h[1],s:1})}
    const pg=(l,v,c)=>`<span style="color:${c}"><b>${l}</b> ${v}</span>`;return i===4||i===5?`${pg("капиляр",pgc,"#e03131")} − ${pg("Боуман",18,"#1c7ed6")} − ${pg("онкотично",32,"#b08900")} = <b>${net>0?"+":""}${net} mmHg</b> · филтрация ≈ <b>${Math.max(0,Math.round(125*net/10))} mL/min</b>${reg===1?" · свита еферентна":reg===2?" · свита аферентна":""}`:i===6?(dmg>0.5?"албуминът преминава → белтък в урината":"зарядът изчезва, израстъците се сливат"):i===2?"албумин: − срещу − → отблъскване":null},
   lab:(i,V)=>[["кръв (капилярен лумен)",V(-14,11.5,0)],["пространство на Боуман",V(-13,-5,0)],["ендотел с фенестри",V(20.5,5.2,6)],["базална мембрана",V(20.5,2.6,6)],["израстъци на подоцитите",V(21,0.4,6)],...(i===1?[["еритроцитът не минава",V(4,10.6,0)]]:[]),...(i===2?[["отрицателни заряди",V(-12,2.6,6.6)]]:[]),...(i===3?[["процепна диафрагма (нефрин)",V(0,-1.6,6.6)]]:[]),...(i===4||i===5?[["↓ 60",V(-20,6,0)],["↑ 18",V(-20,-2,0)],["↑ 32 (белтъци)",V(-21,8.4,0)]]:[])],
   stats:[[["Слоеве","3"],["Пропускливост","× 400 спрямо мускулен капиляр"]],[["Спира","кръвни клетки"]],[["Спира","големи и отрицателни белтъци"],["Албумин във филтрата","< 0,1 %"]],[["Белтък","нефрин"]],[["Нетно налягане","≈ 10 mmHg"],["Филтрация","125 mL/min"],["Филтрационна фракция","≈ 20 %"]],[["Аферентна ↓","филтрация ↓"],["Еферентна ↓","филтрация ↑"]],[["Протеинурия","> 3,5 g/ден"]]]}]});

/* ---------- VII. Киселинно-алкален баланс ---------- */
function abSolve(pco,M,beta){let a=6.5,b=8.1;for(let i=0;i<50;i++){const m=(a+b)/2;(0.03*pco*Math.pow(10,m-6.1)<24+M-beta*(m-7.4))?a=m:b=m}const pH=(a+b)/2;return {pH,hco3:0.03*pco*Math.pow(10,pH-6.1)}}
function abCalc(p){const beta=8+1.15*p.hb,k=p.comp/100,M0=p.V-p.U-p.L;let pco=p.pco,M=M0+k*(p.pco-40)*(p.pco>40?0.3:0.35),r=abSolve(pco,M,beta);
  if(Math.abs(M0)>0.5)for(let i=0;i<30;i++){const ex=M0<0?1.5*r.hco3+8:40+0.7*(r.hco3-24);pco=p.pco+k*(Z.cl(ex,10,60)-40)*0.9;r=abSolve(pco,M,beta)}
  const ag=12+p.U;return {pH:r.pH,hco3:r.hco3,pco,M,M0,beta,ag,cl:140-r.hco3-ag,H:Math.pow(10,9-r.pH)}}
function abDx(p,R){const a=[];if(p.pco>45)a.push(T("респираторна ацидоза"));if(p.pco<35)a.push(T("респираторна алкалоза"));if(R.M0<-2)a.push(T("метаболитна ацидоза"+(p.U>4?" с повишена анионна разлика":" с нормална анионна разлика (хиперхлоремична)")));if(R.M0>2)a.push(T("метаболитна алкалоза"));
  if(!a.length)return "<b>Нормален киселинно-алкален статус</b>: pH 7,35–7,45, P<sub>CO₂</sub> 35–45 mmHg, HCO₃⁻ 22–26 mmol/L.";
  let cmp=p.comp<10?"Без компенсация (остро състояние).":p.comp>80?(a.length===1&&/респ|respir/.test(a[0])?"Бъбреците са компенсирали: променили са HCO₃⁻ в същата посока като P<sub>CO₂</sub>.":a.length===1?"Дишането е компенсирало: P<sub>CO₂</sub> се е променил в същата посока като HCO₃⁻.":""):"Частична компенсация.";
  cmp=T(cmp);return `<b>${a.length>1?T("Смесено нарушение:")+" ":""}${a.join(" + ")}</b>. ${cmp} ${T("pH е")} ${T(R.pH<7.35?"под 7,35 — ацидемия":R.pH>7.45?"над 7,45 — алкалемия":"в нормата")}. ${T("Правило: при компенсация pH се приближава към 7,4, но не го достига и не го преминава.")}`}
Z_EXP.acidbase=[
 {q:"P<sub>CO₂</sub> се покачва остро до 70 mmHg. Какво става с HCO₃⁻ в първите минути?",opts:["Спада силно","Покачва се съвсем малко (около 1 mmol/L на 10 mmHg)","Покачва се до 40 mmol/L"],a:1,set:{pre:"racA"},expl:"В първите минути работят само буферите — точката се движи по буферната линия. Бъбреците задържат HCO₃⁻ едва за 3–5 дни."},
 {q:"При диабетна кетоацидоза какво прави дишането?",opts:["Забавя се","Задълбочава се и P<sub>CO₂</sub> пада","Не се променя"],a:1,set:{pre:"dka"},expl:"H⁺ стимулира хеморецепторите. Очакваният P<sub>CO₂</sub> ≈ 1,5 × HCO₃⁻ + 8. Това е дишането на Кусмаул."},
 {q:"Диария с тежка загуба на HCO₃⁻. Каква е анионната разлика?",opts:["Повишена","Нормална — Cl⁻ се покачва","Понижена"],a:1,set:{pre:"diar"},expl:"Загубеният HCO₃⁻ се замества от Cl⁻ (хиперхлоремична ацидоза). Анионната разлика расте само когато се натрупват неизмерени аниони — лактат, кетотела."},
 {q:"Продължително повръщане. Какво се очаква?",opts:["Метаболитна ацидоза","Метаболитна алкалоза с леко повишен P<sub>CO₂</sub>","Респираторна алкалоза"],a:1,set:{pre:"vom"},expl:"Губи се HCl от стомаха и HCO₃⁻ в кръвта расте. Дишането компенсира слабо — леко се потиска."},
 {q:"Хронична респираторна ацидоза (ХОББ). Защо pH е почти нормално?",opts:["Буферите са безкрайни","Бъбреците задържат HCO₃⁻ и отделят H⁺ като NH₄⁺","Дишането се ускорява"],a:1,set:{pre:"racC"},expl:"За няколко дни тубулите увеличават секрецията на H⁺, образуват нов HCO₃⁻ и отделят повече амоняк."},
 {q:"Отравяне със салицилати: стимулиран дихателен център + органични киселини. pH?",opts:["Винаги силно кисело","Може да е близо до нормата — двете нарушения се неутрализират","Винаги алкално"],a:1,set:{pre:"sal"},expl:"Смесено нарушение: респираторна алкалоза + метаболитна ацидоза. Нормално pH при абнормни P<sub>CO₂</sub> и HCO₃⁻ винаги означава две нарушения."}];
function viewAcidBase(main){zAddStg(main,STG_ABCELL);mkSim(main,{key:"acidbase",h2:"Киселинно-алкален баланс",lead:"Диаграмата на Давенпорт на живо: pH, HCO₃⁻ и P<sub>CO₂</sub> са свързани с уравнението на Хендерсон–Хаселбалх. Промени дишането или метаболитния товар и включи компенсацията.",ch:350,
  sl:[{k:"pco",label:"P<sub>CO₂</sub>, зададен от дишането",min:15,max:90,step:1,value:40,unit:"mmHg",hint:"хиповентилация ↑, хипервентилация ↓"},
      {k:"comp",label:"Компенсация",min:0,max:100,step:5,value:0,unit:"%",hint:"0 — остро; 100 — напълно развита"},
      {k:"hb",label:"Хемоглобин (небикарбонатен буфер)",min:5,max:20,step:0.5,value:15,d:1,show:v=>fmt(v*10,0),unit:"g/L"},
      {k:"U",label:"Неизмерени аниони (лактат, кетотела)",min:0,max:25,step:1,value:0,unit:"mmol/L"},
      {k:"L",label:"Загуба на HCO₃⁻ (диария, тубулна ацидоза)",min:0,max:20,step:1,value:0,unit:"mmol/L"},
      {k:"V",label:"Загуба на H⁺ или прием на основи (повръщане)",min:0,max:20,step:1,value:0,unit:"mmol/L"}],
  pre:{norm:{n:"Норма",info:"Нормална артериална кръв: pH 7,40, P<sub>CO₂</sub> 40 mmHg, HCO₃⁻ 24 mmol/L. Съотношението HCO₃⁻ : разтворен CO₂ е 20 : 1."},
   racA:{n:"Остра респираторна ацидоза",set:{pco:70},info:"Хиповентилация (опиати, обструкция). CO₂ се задържа, точката се движи нагоре-наляво по буферната линия."},
   racC:{n:"Хронична респираторна ацидоза (ХОББ)",set:{pco:70,comp:100},info:"Бъбреците са повишили HCO₃⁻ с около 3–4 mmol/L на всеки 10 mmHg CO₂."},
   ralk:{n:"Респираторна алкалоза (хипервентилация)",set:{pco:25},info:"Тревожност, височина, болка. CO₂ се издишва и pH се покачва. Йонизираният Ca²⁺ пада — изтръпване, тетания."},
   dka:{n:"Диабетна кетоацидоза",set:{U:18,comp:100},info:"Кетокиселините изразходват HCO₃⁻. Анионната разлика е повишена. Дишането е дълбоко (Кусмаул)."},
   lac:{n:"Лактатна ацидоза (шок), без компенсация",set:{U:14},info:"Тъканна хипоксия → млечна киселина. Показано е състоянието, преди дишането да реагира."},
   diar:{n:"Диария",set:{L:12,comp:100},info:"Чревният сок е богат на HCO₃⁻. Губи се основа, а Cl⁻ се покачва."},
   vom:{n:"Повръщане",set:{V:12,comp:100},info:"Губи се стомашна HCl. Обемният дефицит и хипокалиемията поддържат алкалозата."},
   sal:{n:"Салицилати (смесено нарушение)",set:{pco:22,U:10},info:"Салицилатите стимулират дихателния център и едновременно предизвикват метаболитна ацидоза."}},
  exp:Z_EXP.acidbase,calc:abCalc,note:abDx,
  stats:(p,R)=>[["pH",fmt(R.pH,2)],["P<sub>CO₂</sub>",fmt(R.pco,0)+" mmHg"],["HCO₃⁻",fmt(R.hco3,1)+" mmol/L"],["[H⁺]",fmt(R.H,0)+" nmol/L"],["Излишък на основи",(R.M>0?"+":"")+fmt(R.M,0)+" mmol/L"],["Анионна разлика",fmt(R.ag,0)+" mmol/L"],["Cl⁻",fmt(R.cl,0)+" mmol/L"]],
  draw(g,p,R){const X=h=>50+(h-7)/0.8*330,Y=v=>310-v/50*285,iso=P=>{g.beginPath();for(let h=7;h<=7.8;h+=0.01){const v=0.03*P*Math.pow(10,h-6.1);if(v>50)break;h===7?g.moveTo(X(h),Y(v)):g.lineTo(X(h),Y(v))}g.stroke()};
    g.strokeStyle=css("--grid");g.lineWidth=1;for(let h=7;h<=7.81;h+=0.1){g.beginPath();g.moveTo(X(h),Y(0));g.lineTo(X(h),Y(50));g.stroke();Z.T(g,X(h),Y(0)+14,fmt(h,1),{fs:10.5,c:css("--muted")})}
    for(let v=0;v<=50;v+=10){g.beginPath();g.moveTo(X(7),Y(v));g.lineTo(X(7.8),Y(v));g.stroke();Z.T(g,X(7)-6,Y(v)+4,v,{fs:10.5,c:css("--muted"),a:"right"})}
    Z.T(g,X(7.4),Y(0)+29,"pH",{fs:11,c:css("--muted")});g.save();g.translate(14,Y(25));g.rotate(-Math.PI/2);Z.T(g,0,0,"HCO₃⁻, mmol/L",{fs:11,c:css("--muted")});g.restore();
    g.save();g.beginPath();g.rect(X(7),Y(50),330,285);g.clip();
    Z.box(g,X(7.35),Y(26),X(7.45)-X(7.35),Y(22)-Y(26),ZC.grn,null,4,0,0.22);
    [[20,ZC.blue],[40,css("--muted")],[60,ZC.gold],[80,ZC.org]].forEach(([P,c])=>{g.strokeStyle=c;g.lineWidth=1.4;g.setLineDash(P===40?[]:[5,4]);iso(P);g.setLineDash([]);const h=P===20?7.64:P===40?7.6:P===60?7.42:7.3;Z.T(g,X(h)+4,Y(0.03*P*Math.pow(10,h-6.1))-5,P+" mmHg",{fs:10,c,a:"left"})});
    const bl=(M,c,d)=>{g.strokeStyle=c;g.lineWidth=1.6;g.setLineDash(d);g.beginPath();g.moveTo(X(7),Y(24+M-R.beta*(-0.4)));g.lineTo(X(7.8),Y(24+M-R.beta*0.4));g.stroke();g.setLineDash([])};bl(0,css("--ref"),[4,4]);bl(R.M,ZC.vio,[]);
    g.strokeStyle=ZC.red;g.lineWidth=2.4;iso(R.pco);
    rArrow(g,X(7.4),Y(24),X(R.pH),Y(R.hco3),css("--ink"),1.6);g.fillStyle=ZC.red;g.beginPath();g.arc(X(R.pH),Y(R.hco3),6,0,7);g.fill();g.restore();
    Z.T(g,X(7.02),Y(50)+12,"ацидемия",{fs:10.5,c:ZC.org,a:"left"});Z.T(g,X(7.78),Y(50)+12,"алкалемия",{fs:10.5,c:ZC.blue,a:"right"});
    // гамблеграма
    const gx=430,gy=30,gh=250,sc=gh/150,col=(x,parts,ttl)=>{let y=gy+gh;Z.T(g,x+38,gy-8,ttl,{fs:11,w:700});parts.forEach(([v,c,l])=>{const h=v*sc;y-=h;Z.box(g,x,y,76,h,c,css("--panel"),3,1,0.8);if(h>13)Z.T(g,x+38,y+h/2+4,l+" "+fmt(v,0),{fs:10.5,c:"#fff",w:700})})};
    col(gx,[[140,ZC.gold,"Na⁺"],[10,ZC.gray,"др."]],"Катиони");col(gx+100,[[Math.max(0,R.cl),ZC.grn,"Cl⁻"],[R.hco3,ZC.blue,"HCO₃⁻"],[R.ag+10,ZC.vio,"A⁻"]],"Аниони");
    Z.T(g,gx+88,gy+gh+18,"анионна разлика = Na⁺ − Cl⁻ − HCO₃⁻ = "+fmt(R.ag,0),{fs:10.5,c:css("--muted")});
    Z.T(g,gx+88,gy+gh+36,"лилава линия — буферна; червена — изобара на P_CO₂".replace("P_CO₂","PCO₂"),{fs:10,c:css("--muted")})}})}
{const {S,t,tt,box,ln,ar,cr,pth,RED,BLUE,GOLD,VIO,GRN}=BF._;
 BF.zBuf=()=>{let b="";b+=box(20,20,150,60,{f:"none"})+tt(95,44,["Буфери","секунди"],{w:700,w2:400,c2:"var(--muted)",fs2:11});b+=box(190,20,150,60,{f:"none"})+tt(265,44,["Дишане","1–12 минути"],{w:700,w2:400,c2:"var(--muted)",fs2:11});b+=box(360,20,150,60,{f:"none"})+tt(435,44,["Бъбреци","часове до дни"],{w:700,w2:400,c2:"var(--muted)",fs2:11});
  b+=ar([[170,50],[190,50]],{c:"var(--muted)"})+ar([[340,50],[360,50]],{c:"var(--muted)"});
  b+=tt(95,100,["HCO₃⁻/CO₂, фосфат,","белтъци, хемоглобин"],{fs:10.5,c:"var(--muted)"})+tt(265,100,["издишва CO₂;","1–2 пъти силата на буферите"],{fs:10.5,c:"var(--muted)"})+tt(435,100,["отделят H⁺ и NH₄⁺,","връщат и образуват HCO₃⁻"],{fs:10.5,c:"var(--muted)"});
  b+=t(265,140,"най-бързи → най-мощни",{fs:11,w:600});return S(530,150,b,"Три линии на защита срещу промяна на pH")};
 BF.zHH=()=>{let b="";b+=t(230,30,"pH = 6,1 + log ( [HCO₃⁻] / (0,03 × P_CO₂) )".replace("P_CO₂","PCO₂"),{fs:15,w:700});
  b+=box(60,50,150,54,{f:"none",st:BLUE})+tt(135,72,["HCO₃⁻ — бъбреци","метаболитна компонента"],{w:700,w2:400,fs:11.5,fs2:10.5,c:BLUE});b+=box(250,50,150,54,{f:"none",st:RED})+tt(325,72,["PCO₂ — бели дробове","дихателна компонента"],{w:700,w2:400,fs:11.5,fs2:10.5,c:RED});
  b+=t(230,128,"норма: 24 / (0,03 × 40) = 20 → pH = 6,1 + 1,3 = 7,4",{fs:11.5,c:"var(--muted)"});return S(460,140,b,"Уравнение на Хендерсон–Хаселбалх")};
 BF.zTub=()=>{let b="";b+=box(10,20,110,150,{f:"none"})+t(65,38,"лумен",{fs:11,w:700});b+=box(140,20,170,150,{f:"color-mix(in srgb,#f2a65a 18%,var(--panel))"})+t(225,38,"тубулна клетка",{fs:11,w:700});b+=box(330,20,110,150,{f:"none"})+t(385,38,"кръв",{fs:11,w:700});
  b+=t(225,70,"CO₂ + H₂O → H⁺ + HCO₃⁻",{fs:11});b+=t(225,86,"(карбоанхидраза)",{fs:10,c:"var(--muted)"});
  b+=ar([[170,104],[100,104]],{c:RED})+t(65,100,"H⁺",{c:RED,w:700})+ar([[280,104],[350,104]],{c:BLUE})+t(385,108,"нов HCO₃⁻",{c:BLUE,w:700,fs:11});
  b+=tt(65,124,["+ HPO₄²⁻ → H₂PO₄⁻","+ NH₃ → NH₄⁺"],{fs:10.5})+t(65,160,"отделят се с урината",{fs:10,c:"var(--muted)"});
  b+=t(225,140,"глутамин → 2 NH₄⁺ + 2 HCO₃⁻",{fs:10.5,c:GRN});return S(450,180,b,"Секреция на H⁺ и образуване на нов бикарбонат в тубула")};}
Z_BOOK.acidbase={title:"Киселинно-алкален баланс: Хендерсон–Хаселбалх и диаграма на Давенпорт",adv:"жива диаграма на Давенпорт с компенсация и анионна разлика",
 lead:"Концентрацията на H⁺ в кръвта е нищожна — около 40 nmol/L, но тялото я пази много строго, защото от нея зависи работата на всички ензими. По Guyton, гл. 31.",
 secs:[{h:"Киселини, основи и нормално pH",html:`<p>Киселина е вещество, което отдава H⁺, а основа — което го приема. Нормалното pH на артериалната кръв е <b>7,40</b> (венозната ≈ 7,35). Под 7,35 говорим за <b>ацидоза</b>, над 7,45 — за <b>алкалоза</b>. Човек оцелява за часове само между около 6,8 и 8,0.</p><p>Обмяната произвежда два вида киселини: <b>летлива</b> — CO₂ (огромно количество, издишва се от белите дробове), и <b>нелетливи</b> — около 80 mmol на ден сярна, фосфорна и органични киселини, които могат да се отделят само от бъбреците.</p>`},
  {h:"Трите линии на защита",fig:BF.zBuf(),html:`<p>Срещу промяна на pH действат последователно три системи:</p><ul><li><b>Буферите</b> свързват или освобождават H⁺ за части от секундата. Не отстраняват киселината — само я „държат“.</li><li><b>Дихателният център</b> променя вентилацията за минути и така променя CO₂.</li><li><b>Бъбреците</b> действат бавно, но единствени отстраняват нелетливите киселини и възстановяват бикарбоната.</li></ul><p>Най-важният извънклетъчен буфер е <b>бикарбонатният</b>. Неговото pK е 6,1 — далеч от 7,4, но той е мощен, защото двете му съставки се регулират отделно: CO₂ от белите дробове, а HCO₃⁻ от бъбреците. Фосфатният буфер (pK 6,8) е важен в тубулната течност и в клетките, а белтъците (включително хемоглобинът) дават 60–70 % от общата буферна сила на телесните течности.</p>`},
  {h:"Уравнението на Хендерсон–Хаселбалх",fig:BF.zHH(),html:`<p>pH зависи от <b>съотношението</b> между HCO₃⁻ и разтворения CO₂, а не от абсолютните им стойности. Затова, ако едното се промени, тялото може да върне pH, като промени и другото в <b>същата посока</b> — това е компенсацията.</p><ul><li>Първична промяна на <b>P<sub>CO₂</sub></b> → <b>респираторно</b> нарушение.</li><li>Първична промяна на <b>HCO₃⁻</b> → <b>метаболитно</b> нарушение.</li></ul>`},
  {h:"Ролята на бъбреците",fig:BF.zTub(),html:`<p>Бъбреците правят три неща: секретират H⁺, реабсорбират филтрирания HCO₃⁻ (около 4320 mmol на ден) и образуват <b>нов HCO₃⁻</b>.</p><p>В проксималния тубул H⁺ излиза срещу Na⁺ (Na⁺/H⁺ обменник), а в дисталните части — чрез H⁺-ATP-аза в интеркаларните клетки. Урината не може да стане по-кисела от pH ≈ 4,5, затова H⁺ се отделя свързан с буфери: <b>фосфат</b> и най-вече <b>амоняк</b> (NH₄⁺), който се образува от глутамин. При хронична ацидоза отделянето на NH₄⁺ може да нарасне десетократно.</p>`},
  {h:"Четирите основни нарушения",html:`<ul><li><b>Респираторна ацидоза</b>: P<sub>CO₂</sub> ↑ (хиповентилация). Компенсация: бъбреците повишават HCO₃⁻.</li><li><b>Респираторна алкалоза</b>: P<sub>CO₂</sub> ↓ (хипервентилация, височина). Компенсация: бъбреците отделят HCO₃⁻.</li><li><b>Метаболитна ацидоза</b>: HCO₃⁻ ↓ (диария, бъбречна недостатъчност, кетоацидоза, лактат). Компенсация: хипервентилация.</li><li><b>Метаболитна алкалоза</b>: HCO₃⁻ ↑ (повръщане, диуретици, излишък на алдостерон). Компенсация: лека хиповентилация.</li></ul><p><b>Анионната разлика</b> (Na⁺ − Cl⁻ − HCO₃⁻, нормално 8–16 mmol/L) разделя метаболитните ацидози: повишена е при натрупване на неизмерени аниони (кетотела, лактат, отрови, уремия) и нормална — когато загубеният HCO₃⁻ се замества от Cl⁻ (диария, тубулна ацидоза).</p>`}],
 key:["Нормално: pH 7,40; P<sub>CO₂</sub> 40 mmHg; HCO₃⁻ 24 mmol/L; съотношение 20 : 1.","Буфери (секунди) → дишане (минути) → бъбреци (дни).","pH = 6,1 + log(HCO₃⁻ / 0,03 × P<sub>CO₂</sub>).","Компенсацията променя другата величина в същата посока и никога не „прескача“ 7,4.","Бъбрекът отделя H⁺ главно като NH₄⁺ и с фосфата и образува нов HCO₃⁻.","Анионна разлика: норма 8–16 mmol/L; ↑ при кетоацидоза, лактат, уремия."]};
Z_TESTS.acidbase=[
 {q:"Какво е нормалното съотношение HCO₃⁻ : разтворен CO₂ в артериалната кръв?",opts:["1 : 1","10 : 1","20 : 1","40 : 1"],a:2,expl:"24 mmol/L : 1,2 mmol/L = 20; log 20 = 1,3 и pH = 6,1 + 1,3 = 7,4."},
 {q:"Коя система реагира най-бързо на внезапно добавена киселина?",opts:["Бъбреците","Дишането","Химичните буфери","Черният дроб"],a:2,expl:"Буферите действат за части от секундата, дишането — за минути, бъбреците — за часове и дни."},
 {q:"pH 7,25; P<sub>CO₂</sub> 60 mmHg; HCO₃⁻ 26 mmol/L. Какво е нарушението?",opts:["Остра респираторна ацидоза","Метаболитна ацидоза","Метаболитна алкалоза","Респираторна алкалоза"],a:0,expl:"Висок P<sub>CO₂</sub> и ниско pH; HCO₃⁻ е почти непроменен — още няма бъбречна компенсация."},
 {q:"pH 7,30; P<sub>CO₂</sub> 28 mmHg; HCO₃⁻ 13 mmol/L. Какво е нарушението?",opts:["Респираторна алкалоза","Метаболитна ацидоза с дихателна компенсация","Респираторна ацидоза","Метаболитна алкалоза"],a:1,expl:"Нисък HCO₃⁻ е първичен; ниският P<sub>CO₂</sub> е компенсация (1,5 × 13 + 8 ≈ 28)."},
 {q:"С кой буфер се отделя по-голямата част от H⁺ в урината при хронична ацидоза?",opts:["Бикарбонат","Фосфат","Амоняк (NH₄⁺)","Белтъци"],a:2,expl:"Образуването на NH₄⁺ от глутамин може да нарасне многократно и е главният адаптивен механизъм."},
 {q:"При кое състояние анионната разлика е нормална?",opts:["Диабетна кетоацидоза","Лактатна ацидоза","Диария","Отравяне с метанол"],a:2,expl:"При диария се губи HCO₃⁻, а Cl⁻ се покачва — хиперхлоремична ацидоза."},
 {q:"Какво предизвиква продължителното повръщане на стомашно съдържимо?",opts:["Метаболитна ацидоза","Метаболитна алкалоза","Респираторна ацидоза","Не променя pH"],a:1,expl:"Губи се HCl; за всеки секретиран H⁺ в кръвта влиза един HCO₃⁻."},
 {q:"Колко е минималното pH на урината?",opts:["≈ 1,0","≈ 4,5","≈ 6,8","≈ 7,4"],a:1,expl:"H⁺-ATP-азата може да създаде градиент около 900 пъти спрямо плазмата — до pH ≈ 4,5. Затова са нужни буфери в урината."},
 {q:"Как се променя дишането при метаболитна алкалоза?",opts:["Ускорява се силно","Леко се потиска","Спира","Не се променя"],a:1,expl:"По-малко H⁺ → по-слаб стимул за дихателния център; P<sub>CO₂</sub> се покачва леко. Компенсацията е ограничена от хипоксията."}];
Z_NAMES.acidbase="Киселинно-алкален баланс";Z_VIEWS.acidbase=viewAcidBase;
Z_GL.push({t:"Ацидоза и алкалоза",re:"ацидоз[а-я]*|алкалоз[а-я]*|ацидеми[а-я]*|алкалеми[а-я]*",d:"Ацидоза — процес, който понижава pH под 7,35; алкалоза — повишава го над 7,45. Респираторни са при първична промяна на P<sub>CO₂</sub>, метаболитни — при първична промяна на HCO₃⁻."},
 {t:"Уравнение на Хендерсон–Хаселбалх",re:"Хендерсон[–-]Хаселбалх",d:"pH = pK + log([основа]/[киселина]). За бикарбонатния буфер: pH = 6,1 + log(HCO₃⁻ / 0,03 × P<sub>CO₂</sub>)."},
 {t:"Буфер",re:"буфер(?![а-я]*н[а-я]* зон)[а-я]*",d:"Двойка слаба киселина и нейната основа, която свързва или освобождава H⁺ и така намалява промяната на pH. Най-силен е, когато pH е близо до pK."},
 {t:"Диаграма на Давенпорт",re:"Давенпорт",d:"Графика на HCO₃⁻ срещу pH с изобари на P<sub>CO₂</sub>. Показва дали нарушението е респираторно (движение по буферната линия) или метаболитно (движение по изобарата)."},
 {t:"Анионна разлика",re:"анион[а-я]* разлик[а-я]*",d:"Na⁺ − (Cl⁻ + HCO₃⁻); нормално 8–16 mmol/L. Отразява неизмерените аниони. Повишена е при кетоацидоза, лактатна ацидоза, уремия и някои отравяния."},
 {t:"Компенсация",re:"компенсаци[а-я]*",d:"Вторична промяна на P<sub>CO₂</sub> (от дишането) или на HCO₃⁻ (от бъбреците), която връща pH към нормата при първично киселинно-алкално нарушение."},
 {t:"Излишък на основи (BE)",re:"излиш[а-я]* на основи",d:"Количеството силна киселина или основа, нужно да върне 1 L кръв до pH 7,4 при P<sub>CO₂</sub> 40 mmHg. Мери метаболитната компонента; норма ±2 mmol/L."},
 {t:"Амониев йон (NH₄⁺)",re:"NH₄⁺|амоня[а-я]*",d:"Образува се в тубулните клетки от глутамин. Отделя H⁺ с урината и всеки NH₄⁺ означава един нов HCO₃⁻ в кръвта."},
 {t:"Кетоацидоза",re:"кетоацидоз[а-я]*|кетотел[а-я]*|кетокиселин[а-я]*",d:"Метаболитна ацидоза от натрупване на ацетоацетат и β-хидроксибутират при липса на инсулин или гладуване."});

