  exp:Z_EXP.thermo,init:()=>({Tc:37,Ts:33.2,anti:0}),
  step(s,p,dt){const F=thFlux(s,p);s.Tc=Z.cl(s.Tc+(F.M-F.K*(s.Tc-s.Ts))/194000*dt,24,44);s.Ts=Z.cl(s.Ts+(F.K*(s.Tc-s.Ts)-F.dry-F.ev)/49000*dt,-5,44)},
