    Z.org(g,470,116,150,66,ZC.blue,"Бъбрек","в урината "+fmt(R.ur*40,0)+" mg",R.ur/8);Z.arr(g,390,150,470,150,ZC.blue,Z.cl(R.ur/1.2,0.4,7),"");
    Z.org(g,470,216,150,56,ZC.teal,"Калцитриол",fmt(s.D*100,0)+" %",s.D/2.5);Z.arr(g,545,182,545,216,ZC.teal,Z.cl(s.D*2,0.3,6),"1α-хидроксилаза");Z.arr(g,470,256,170,262,ZC.teal,Z.cl(s.D*2,0.3,6),"");
    Z.arr(g,236,62,120,96,ZC.vio,Z.cl(s.PTH*2,0.3,7),"");Z.arr(g,410,62,530,116,ZC.vio,Z.cl(s.PTH*2,0.3,7),"");
