/* ===== XI. Зрение, слух, равновесие ===== */
const EYE_B=1000/17;
function eyeCalc(p){const L=17*p.len/24,need=1000/L,err=EYE_B-need,amax=Math.max(0.5,Math.min(14,16.5-0.3*p.age)),V=1/p.dist,want=V+need-EYE_B-p.G,acc=Math.max(0,Math.min(amax,want)),P=EYE_B+acc+p.G,di=1000/(P-V),def=P-V-need,
  farV=EYE_B+p.G-need,nearV=farV+amax;return {L,err,amax,acc,di,def,far:farV>0.02?1/farV:Infinity,near:nearV>0.02?1/nearV:Infinity,want}}
