/* ===== XII. ЦНС: рефлекси и мускулно вретено ===== */
function rfStep(s,p,dt,t){const gam=0.4+1.2*p.gam/100,gain=(1+3.2*(1-p.sup/100))*p.arc/100,tap=(t>=s.tt&&t-s.tt<0.04)?p.H/100*1.4:0,
  x=tap+Math.max(0,-s.th)*0.9+Math.max(0,-s.om)*0.09,Ia=Math.min(3,gam*x)*(p.arc>0?1:0.0+1);s.buf.push(Ia);const del=s.buf.length>s.nd?s.buf.shift():0;s.Ia=Ia;s.del=del*p.arc/100;
  s.a+=(Math.min(1,gain*del*0.9)-s.a)*Math.min(1,dt/0.045);s.om+=(-57*s.th-(5+4*p.sup/100)*s.om+300*s.a)*dt;s.th+=s.om*dt;if(s.th>1.2){s.th=1.2;s.om=Math.min(0,s.om)}if(s.th<-0.5){s.th=-0.5;s.om=Math.max(0,s.om)}s.pk=Math.max(s.pk,s.th);if(s.a>0.05&&s.lat==null&&t>s.tt)s.lat=t-s.tt}
Z_EXP.reflex=[
 {q:"Чукчето удря сухожилието под капачката. Кой мускул се съкращава?",opts:["Същият, който е разтегнат (четириглавият)","Антагонистът му","И двата"],a:0,set:{pre:"norm",ev:"tap"},expl:"Рефлексът на разтягане връща мускула към предишната дължина. Антагонистът се отпуска чрез реципрочно задържане."},
 {q:"Пациентът стиска и дърпа сключените си ръце (маневра на Йендрасик). Какво става с рефлекса?",opts:["Отслабва","Усилва се","Изчезва"],a:1,set:{pre:"jen",ev:"tap"},expl:"Усилието повишава γ-тонуса и възбудимостта на мотоневроните — вретената стават по-чувствителни."},
 {q:"Прекъснат е пирамидният път над сегмента (увреда на горния мотоневрон). Какъв е рефлексът?",opts:["Липсва","Нормален","Усилен, с ритмични повторения (клонус)"],a:2,set:{pre:"umn",ev:"tap"},expl:"Отпада задържането отгоре. Примката става толкова чувствителна, че всяко връщане на крака я задейства отново."},
 {q:"Прекъснат е периферният нерв или предният рог (долен мотоневрон). Какъв е рефлексът?",opts:["Липсва","Усилен","Забавен, но нормален по сила"],a:0,set:{pre:"lmn",ev:"tap"},expl:"Рефлексната дъга е прекъсната — арефлексия, нисък тонус и атрофия."}];
function viewReflex(main){zAddStg(main,STG_REFARC);zAddStg(main,STG_REFCELL);mkSim(main,{key:"reflex",h2:"Коленен рефлекс",lead:"Удари сухожилието и проследи сигнала: вретено → Ia влакно → гръбначен мозък → α-мотоневрон → мускул. Времето е забавено 4 пъти.",ch:330,speed:0.25,dtmax:0.001,recdt:0.004,hmax:500,
  sl:[{k:"H",label:"Сила на удара",min:5,max:100,step:5,value:60,unit:"%"},{k:"gam",label:"γ-тонус (чувствителност на вретеното)",min:0,max:100,step:5,value:50,unit:"%"},{k:"sup",label:"Задържане от главния мозък",min:0,max:100,step:5,value:100,unit:"%"},{k:"arc",label:"Проводимост на рефлексната дъга",min:0,max:100,step:5,value:100,unit:"%"}],
  ev:{tap:{l:"Удари с чукчето",f:(s,p,t)=>{s.tt=t+0.01;s.pk=0;s.lat=null}}},
  pre:{norm:{n:"Здрав човек",info:"Натисни „Удари с чукчето“. Латентното време е около 20–30 ms — толкова трябва на сигнала да стигне до гръбначния мозък и обратно през един-единствен синапс."},
   jen:{n:"Маневра на Йендрасик",set:{gam:95},info:"Произволното усилие с ръцете повишава γ-тонуса и възбудимостта на мотоневроните. Използва се, когато рефлексът трудно се предизвиква."},
   umn:{n:"Увреда на горния мотоневрон (спастичност)",set:{sup:0,gam:70},info:"Липсва задържането от кората и ствола: хиперрефлексия, повишен тонус, клонус, положителен рефлекс на Бабински."},
   lmn:{n:"Увреда на долния мотоневрон или нерва",set:{arc:0},info:"Дъгата е прекъсната: арефлексия, отпуснат мускул, атрофия, фасцикулации."}},
  exp:Z_EXP.reflex,init:()=>({th:0,om:0,a:0,Ia:0,del:0,buf:[],nd:28,tt:1e9,pk:0,lat:null}),
  step:(s,p,dt,t)=>rfStep(s,p,dt,t),rec:(s,p,t)=>[t,s.Ia,s.a,s.th*57.3],calc:(p,s)=>({}),
  stats:(p,R,s)=>[["Изправяне на подбедрицата",fmt(s.th*57.3,0)+"°"],["Най-голямо отклонение",fmt(s.pk*57.3,0)+"°"],["Латентно време",s.lat!=null?fmt(s.lat*1000,0)+" ms":"—"],["Ia влакно",s.Ia>0.05?"импулси":"покой"],["α-мотоневрон",s.a>0.05?"активен":"покой"]],
  note:(p,R,s)=>p.arc<5?"<b>Арефлексия</b>: сигналът не може да премине дъгата. Така изглежда увреда на периферния нерв, на задното коренче или на предния рог.":p.sup<30?"<b>Хиперрефлексия и клонус</b>: без задържането отгоре примката се самоподдържа — всяко връщане на крака разтяга мускула и предизвиква ново съкращение.":s.a>0.05?"α-мотоневроните на четириглавия мускул са активни, а тези на сгъвачите са <b>задържани</b> от интерневрон (реципрочна инервация).":"Вретеното отчита и дължината, и скоростта на разтягане. Рефлексът работи постоянно и неусетно — поддържа мускулния тонус и стойката.",
  plots:[{f:(p,R,h)=>{const x=h.map(a=>a[0]),T=x.length?x[x.length-1]:2;return {xmin:Math.max(0,T-2),xmax:Math.max(2,T),ymin:0,ymax:3,xlabel:"време, s",ylabel:"активност (отн.)",series:[{x,y:h.map(a=>a[1]),color:css("--accent"),width:2},{x,y:h.map(a=>a[2]*2.4),color:css("--accent2"),width:2}]}}},
   {f:(p,R,h)=>{const x=h.map(a=>a[0]),T=x.length?x[x.length-1]:2;return {xmin:Math.max(0,T-2),xmax:Math.max(2,T),ymin:-30,ymax:75,xlabel:"време, s",ylabel:"ъгъл на изправяне, °",hlines:[{y:0,color:css("--grid")}],series:[{x,y:h.map(a=>a[3]),color:css("--accent4"),width:2.2}]}}}],
  legend:`<span><i style="background:var(--accent)"></i>Ia влакно (вретено)</span><span><i style="background:var(--accent2)"></i>α-мотоневрон / мускул</span><span><i style="background:var(--accent4)"></i>движение на подбедрицата</span>`,
  draw(g,p,R,t,dt,s){const kx=150,ky=150,a=Math.PI/2-s.th,fx=kx+Math.cos(a)*120,fy=ky+Math.sin(a)*120,tapping=t>=s.tt-0.012&&t<s.tt+0.06;
    // бедро и подбедрица
    window.__leg(g,kx,ky,a,s.a,s.a<=0.05);
    Z.T(g,70,ky-38,"четириглав мускул",{fs:10.5,c:ZC.red,w:700});Z.T(g,74,ky+34,"сгъвачи (задържани)",{fs:10.5,c:ZC.blue});
    // чукче
    const hx=kx+20+(tapping?0:26),hy=ky+26+(tapping?0:8);g.save();g.translate(hx,hy);g.rotate(-0.5);const hg=g.createLinearGradient(0,-8,0,8);hg.addColorStop(0,"#ff8787");hg.addColorStop(1,"#c92a2a");g.fillStyle=hg;g.beginPath();g.moveTo(0,0);g.lineTo(24,-11);g.lineTo(24,11);g.closePath();g.fill();g.strokeStyle="#7d1a1a";g.lineWidth=1;g.stroke();const mg=g.createLinearGradient(0,-3,0,3);mg.addColorStop(0,"#e9ecef");mg.addColorStop(1,"#868e96");g.fillStyle=mg;g.fillRect(22,-2.5,66,5);g.fillStyle="#495057";g.fillRect(70,-3.5,20,7);g.restore();
    // гръбначен мозък
    const cx=500,cy=120;{const wg=g.createRadialGradient(cx-30,cy-30,10,cx,cy,96);wg.addColorStop(0,"#fbf6ec");wg.addColorStop(1,"#e6dcc6");g.fillStyle=wg;}g.strokeStyle="#b9a88a";g.lineWidth=1.5;g.beginPath();g.ellipse(cx,cy,92,74,0,0,7);g.fill();g.stroke();g.fillStyle="#cdb7a6";g.beginPath();g.moveTo(cx-10,cy-50);g.bezierCurveTo(cx-60,cy-66,cx-52,cy-8,cx-14,cy-6);g.lineTo(cx-18,cy+10);g.bezierCurveTo(cx-70,cy+16,cx-54,cy+62,cx-8,cy+44);g.lineTo(cx+8,cy+44);g.bezierCurveTo(cx+54,cy+62,cx+70,cy+16,cx+18,cy+10);g.lineTo(cx+14,cy-6);g.bezierCurveTo(cx+52,cy-8,cx+60,cy-66,cx+10,cy-50);g.closePath();g.fill();
    Z.T(g,cx,cy-84,"гръбначен мозък (L2–L4)",{fs:10.5,c:css("--muted")});
    const ia=[[kx-60,ky-22],[250,60],[400,62],[cx-40,cy-40],[cx-30,cy+26]],al=[[cx-30,cy+30],[400,214],[250,218],[kx-70,ky-10]],fl=[[cx-12,cy+34],[410,250],[250,256],[kx-80,ky+16]];
    const path=(P,c,w,al2)=>{g.strokeStyle=c;g.lineWidth=w;g.globalAlpha=al2;g.beginPath();g.moveTo(P[0][0],P[0][1]);for(let i=1;i<P.length;i++)g.lineTo(P[i][0],P[i][1]);g.stroke();g.globalAlpha=1};
    path(ia,ZC.gold,2.2,p.arc<5?0.3:1);path(al,ZC.red,2.2,p.arc<5?0.3:1);path(fl,ZC.blue,1.6,0.6);
    if(s.Ia>0.05&&p.arc>=5)Z.dots(g,ia,(t*14)%1,ZC.gold,4,3.6);if(s.a>0.05)Z.dots(g,al,(t*14)%1,ZC.red,4,3.6);
    g.fillStyle=ZC.red;g.beginPath();g.arc(cx-30,cy+30,7,0,7);g.fill();g.fillStyle=ZC.vio;g.beginPath();g.arc(cx-20,cy+8,5,0,7);g.fill();g.fillStyle=ZC.blue;g.globalAlpha=s.a>0.05?0.35:1;g.beginPath();g.arc(cx-12,cy+36,6,0,7);g.fill();g.globalAlpha=1;
    Z.T(g,330,50,"Ia аферентно влакно",{fs:10.5,c:ZC.gold,w:700});Z.T(g,330,206,"α-мотоневрон",{fs:10.5,c:ZC.red,w:700});Z.T(g,330,272,"към сгъвачите ⊖",{fs:10.5,c:ZC.blue});Z.T(g,cx+34,cy+6,"задържащ интерневрон",{fs:9.5,c:ZC.vio});
    if(p.sup<100){Z.T(g,cx+40,22,"задържане от мозъка: "+p.sup+" %",{fs:10.5,c:ZC.red,w:700})}Z.arr(g,cx+20,30,cx-8,cy+18,ZC.grn,p.sup/40,"");
    Z.T(g,480,300,s.lat!=null?"латентно време ≈ "+fmt(s.lat*1000,0)+" ms":"един синапс → най-бързият рефлекс",{fs:11.5,w:700,c:css("--ink")})}})}
{const {S,t,tt,box,ln,ar,cr,pth,RED,BLUE,GOLD,VIO,GRN}=BF._;
 BF.zArc=()=>{let b="";const B=(x,l1,l2,c)=>box(x,20,92,40,{f:"none",st:c})+tt(x+46,36,[l1,l2],{fs:10.5,lh:13,c});
  b+=B(6,"Рецептор","вретено",GOLD)+B(112,"Аферентно","влакно (Ia)",GOLD)+B(218,"Център","гръбначен мозък",VIO)+B(324,"Еферентно","влакно (α)",RED)+B(430,"Ефектор","мускул",RED);[98,204,310,416].forEach(x=>b+=ar([[x,40],[x+14,40]],{c:"var(--muted)",w:1.4}));
  b+=pth("M476 60 C 476 96, 52 96, 52 64",{c:GRN,w:1.4,dash:"5 4"})+t(264,104,"съкращението скъсява мускула и премахва дразнителя — отрицателна обратна връзка",{fs:10,c:GRN});return S(530,112,b,"Петте звена на рефлексната дъга")};
 BF.zSpGo=()=>{let b="";b+=t(130,16,"Мускулно вретено",{fs:11.5,w:700,c:GOLD})+t(390,16,"Сухожилен орган на Голджи",{fs:11.5,w:700,c:BLUE});
  b+=tt(130,36,["успоредно на влакната","мери ДЪЛЖИНА и скорост","влакна Ia (и II)","→ възбужда собствения мускул","γ-мотоневрони го настройват"],{fs:10.5,lh:16})+tt(390,36,["последователно, в сухожилието","мери НАПРЕЖЕНИЕ","влакна Ib","→ задържа собствения мускул","(през интерневрон)"],{fs:10.5,lh:16})+ln(260,8,260,116,{c:"var(--line)"});return S(520,122,b,"Двата проприорецептора на мускула")}}
Z_BOOK.reflex={title:"Рефлекси и мускулно вретено",adv:"коленен рефлекс с латентно време, клонус и арефлексия; мускулно вретено в 3D и задържащ синапс на молекулно ниво",
 lead:"Гръбначният мозък не е просто кабел: в него има готови програми, които реагират на разтягане, натоварване и болка за десетки милисекунди — преди мозъкът да е разбрал. По Guyton, гл. 55.",
 secs:[{h:"Рефлексна дъга",fig:BF.zArc(),html:`<p>Рефлексът е стереотипен отговор на дразнител, осъществен от нервната система. Пътят му — <b>рефлексната дъга</b> — има пет звена: рецептор, аферентно влакно, център, еферентно влакно, ефектор. Според броя на синапсите в центъра рефлексите са <b>моносинаптични</b> (само рефлексът на разтягане) и <b>полисинаптични</b>.</p><p>В предните рога има <b>α-мотоневрони</b> (към работните мускулни влакна; един неврон с влакната си е двигателна единица), <b>γ-мотоневрони</b> (към влакната на вретеното) и много интерневрони. <b>Клетките на Реншоу</b> се възбуждат от колатерал на α-мотоневрона и го задържат обратно — ограничават разряда му.</p>`},
  {h:"Видове рефлекси",html:`<ul><li><b>По броя на синапсите</b>: моносинаптични (рефлекс на разтягане) и полисинаптични (всички останали).</li><li><b>По рецептора</b>: проприоцептивни (вретено, орган на Голджи), екстероцептивни (кожа — сгъвателен, коремни, плантарен рефлекс) и интероцептивни (от вътрешните органи и съдовете — барорефлекс, рефлекси на изпразване).</li><li><b>По ефектора</b>: <b>соматични</b> (скелетен мускул; еферентът е един α-мотоневрон) и <b>вегетативни</b> (гладък мускул, сърце, жлеза; еферентът е от два неврона със синапс в ганглий).</li><li><b>По нивото на центъра</b>: спинални, булбарни (кашляне, гълтане, повръщане, барорефлекс), мезенцефални (зеничен), с участие на кората.</li><li><b>По биологичния смисъл</b>: защитни (сгъвателен, роговичен, кашличен), позно-тонични, локомоторни, хранителни, полови.</li><li><b>По произхода</b>: <b>безусловни</b> — вродени, видово постоянни, с готова дъга; и <b>условни</b> — придобити през живота чрез съчетаване на безразличен дразнител с безусловен (Павлов), изискват кора и угасват без подкрепление.</li></ul><p>В 3D модела „Рефлексните дъги“ са показани трите основни спинални рефлекса: на разтягане, сухожилният на Голджи и сгъвателният с кръстосания разгъвателен.</p>`},
  {h:"Мускулно вретено",fig:BF.zSpGo(),html:`<p>Вретеното е капсула с 3–12 тънки <b>интрафузални влакна</b>, разположена <i>успоредно</i> на работните влакна. Средната част на всяко влакно не се съкращава; около нея е навито <b>първичното (Ia) окончание</b>, което отчита и дължината, и скоростта на промяната ѝ (динамичен отговор). Вторичните окончания (влакна тип II) отчитат главно дължината.</p><p>Краищата на интрафузалните влакна се съкращават под действие на <b>γ-мотоневроните</b>. Това опъва средната част и поддържа вретеното чувствително, когато мускулът се скъси. При произволно движение мозъкът активира α и γ едновременно (<b>α–γ коактивация</b>).</p>`},
  {h:"Рефлекс на разтягане (миотатичен)",html:`<p>Разтягането на мускула → Ia влакна → <b>пряко</b> върху α-мотоневроните на същия мускул → съкращение. Едновременно колатерал възбужда задържащ интерневрон към мотоневроните на антагониста (<b>реципрочно задържане</b>).</p><p>Рефлексът има динамична част (бързият отговор при удар с чукче) и статична (поддържа <b>мускулния тонус</b> и стойката, изглажда движенията). Клинично се изследват коленният (L2–L4), ахилесовият (S1–S2), бицепсовият (C5–C6) и трицепсовият (C7–C8) рефлекс.</p>`},
  {h:"Сухожилен рефлекс на Голджи",html:`<p>Сухожилният орган е разположен <i>последователно</i> с мускула и отчита <b>напрежението</b>. Ib влакната му чрез задържащ интерневрон потискат α-мотоневроните на същия мускул. Така се изравнява натоварването между влакната, а при опасно голямо напрежение мускулът рязко се отпуска (реакция на удължаване) — предпазва се сухожилието.</p>`},
  {h:"Сгъвателен и кръстосан разгъвателен рефлекс",html:`<p>Болков дразнител върху крайник → полисинаптична верига → съкращение на сгъвачите и отдръпване (<b>защитен сгъвателен рефлекс</b>). Латентното време е по-дълго, а след края на дразнителя отговорът продължава (следразряд в кръгови вериги от интерневрони).</p><p>След 0,2–0,5 s срещуположният крайник се изпъва (<b>кръстосан разгъвателен рефлекс</b>) и поема тежестта на тялото. Гръбначният мозък съдържа и готови генератори на ритмични движения за ходене.</p>`},
  {h:"Значение за клиниката",html:`<ul><li><b>Долен мотоневрон</b> (преден рог, коренче, нерв): отпусната парализа, арефлексия, атрофия, фасцикулации.</li><li><b>Горен мотоневрон</b> (кора, пирамиден път): спастична парализа, хиперрефлексия, клонус, рефлекс на Бабински; атрофията е слаба.</li><li><b>Спинален шок</b>: веднага след прекъсване на гръбначния мозък всички рефлекси под нивото изчезват за дни до седмици, после се връщат и стават усилени.</li></ul>`}],
 key:["Рефлексна дъга: рецептор → аферент → център → еферент → ефектор.","Вретено: успоредно, дължина и скорост, Ia → възбужда същия мускул (моносинаптично).","Голджи: последователно, напрежение, Ib → задържа същия мускул.","γ-мотоневроните поддържат чувствителността на вретеното; α–γ коактивация.","Реципрочно задържане на антагониста чрез глицинов интерневрон.","Горен мотоневрон: хиперрефлексия и клонус; долен: арефлексия и атрофия."]};
Z_TESTS.reflex=[
 {q:"Кой рефлекс е моносинаптичен?",opts:["Сгъвателният","Рефлексът на разтягане","Сухожилният рефлекс на Голджи","Кръстосаният разгъвателен"],a:1,expl:"Ia влакното завършва направо върху α-мотоневрона."},
 {q:"Какво отчита мускулното вретено?",opts:["Напрежението в сухожилието","Дължината на мускула и скоростта на промяната ѝ","Болка","Температура"],a:1,expl:"Напрежението се отчита от сухожилния орган на Голджи."},
 {q:"Каква е ролята на γ-мотоневроните?",opts:["Съкращават работните влакна","Съкращават краищата на интрафузалните влакна и настройват чувствителността","Задържат α-мотоневроните","Провеждат болка"],a:1,expl:"Без тях вретеното би „провиснало“ при скъсяване на мускула."},
 {q:"Как Ib влакната от органа на Голджи действат върху собствения мускул?",opts:["Възбуждат го пряко","Задържат го чрез интерневрон","Не му влияят","Възбуждат го чрез γ-мотоневрони"],a:1,expl:"Това е обратен миотатичен рефлекс — защита от прекомерно напрежение."},
 {q:"Какво е реципрочно задържане?",opts:["Задържане на мотоневрона от собствения му колатерал","Задържане на мотоневроните на антагониста при активиране на агониста","Задържане от малкия мозък","Умора на синапса"],a:1,expl:"Осъществява се от интерневрон, отделящ глицин."},
 {q:"Кои сегменти затварят коленния рефлекс?",opts:["C5–C6","L2–L4","S1–S2","Th10–Th12"],a:1,expl:"Ахилесовият е S1–S2, бицепсовият — C5–C6."},
 {q:"Какво е характерно за увреда на горния мотоневрон?",opts:["Арефлексия и атрофия","Хиперрефлексия, спастичност, клонус","Фасцикулации","Нисък тонус"],a:1,expl:"Отпада задържащото влияние върху гръбначните рефлекси."},
 {q:"Какво представляват клетките на Реншоу?",opts:["Сетивни неврони","Задържащи интерневрони, които ограничават разряда на α-мотоневрона","γ-мотоневрони","Глиални клетки"],a:1,expl:"Възвратно задържане: колатералът на аксона ги възбужда, а те задържат самия мотоневрон."},
 {q:"Защо отдръпването на ръката продължава и след като убождането е спряло?",opts:["Заради умора","Заради следразряд в кръгови вериги от интерневрони","Заради бавни C влакна в мускула","Заради Реншоу"],a:1,expl:"Полисинаптичните рефлекси имат реверберация."},
 {q:"Стрихнинът предизвиква гърчове, защото…",opts:["Блокира ацетилхолиновите рецептори","Блокира глициновите рецептори на мотоневроните","Отваря Na⁺ канали","Блокира освобождаването на глутамат"],a:1,expl:"Отпада задържането — всяко дразнене дава генерализирано съкращение."}];
