const EEG_ST={open:{b:[[20,7],[27,5],[10,3]],n:5,eog:0.3,emg:1,band:[5,8,15,72]},closed:{b:[[10,38],[9.2,14],[20,4]],n:4,eog:0.05,emg:0.8,band:[5,10,70,15],mod:0.25},n1:{b:[[5.5,22],[7,12],[10,6]],n:5,eog:0.15,emg:0.6,band:[12,60,18,10],slow:1},
 n2:{b:[[5,18],[3,14]],n:5,eog:0.02,emg:0.45,band:[30,45,15,10],sp:1},n3:{b:[[1.2,85],[2.1,40],[0.7,35]],n:5,eog:0.02,emg:0.35,band:[80,12,5,3]},rem:{b:[[18,7],[6,9],[25,5]],n:5,eog:1,emg:0.04,band:[8,30,12,50],rem:1},abs:{b:[],n:3,eog:0.1,emg:0.6,band:[75,15,5,5],sw:3},gm:{b:[[16,70],[22,45]],n:40,eog:0.3,emg:3,band:[10,15,25,50]}};
const EEG_NAME={open:"β-ритъм",closed:"α-ритъм",n1:"θ-ритъм",n2:"сънни вретена и K-комплекси",n3:"δ-ритъм",rem:"бърза нисковолтова активност",abs:"комплекси „шип–вълна“ 3 Hz",gm:"високоволтови шипове"};
function eegStep(s,p,dt,t){const S=EEG_ST[p.pre]||EEG_ST.open,g=p.gain/100;if(s.ph.length<6)for(let i=0;i<6;i++)s.ph.push(Math.random()*6.28);let v=0;
  S.b.forEach(([f,a],i)=>{s.ph[i]+=6.283*f*(1+0.08*Math.sin(t*0.9+i*2.1)+0.05*(Math.random()-0.5))*dt;v+=a*Math.sin(s.ph[i])*(S.mod?0.75+S.mod*Math.sin(t*0.7+i):1)});s.nz+=(Math.random()-0.5-s.nz*0.2);v+=S.n*s.nz*0.8;
  if(S.sp){const u=(t%4.2);if(u<0.9)v+=24*Math.sin(6.283*13*t)*Math.sin(Math.PI*u/0.9);const k=((t+2)%7.5);if(k<0.9)v+=k<0.25?-70*Math.sin(Math.PI*k/0.25):55*Math.sin(Math.PI*(k-0.25)/0.65)}
  if(S.sw){const u=(t*S.sw)%1;v+=u<0.1?150*Math.sin(Math.PI*u/0.1):-95*Math.sin(Math.PI*(u-0.1)/0.9)}
  let eo=S.eog*3*s.nz;if(S.rem){const u=(t%2.6);eo+=u<1.2?45*Math.sign(Math.sin(t*9))*Math.exp(-((u%0.4)*8)):0}if(S.slow)eo+=30*Math.sin(t*1.4);if(p.pre==="open"){const u=t%3.5;if(u<0.25)eo+=70*Math.sin(Math.PI*u/0.25)}
  const em=S.emg*(Math.random()-0.5)*70;s.buf.push([t,v*g,eo,em]);while(s.buf.length&&s.buf[0][0]<t-6)s.buf.shift()}
Z_EXP.eeg=[
 {q:"Будният човек затваря очи и се отпуска. Какъв ритъм се появява в тилната област?",opts:["β (14–30 Hz)","α (8–13 Hz)","δ (под 3,5 Hz)"],a:1,set:{pre:"closed"},expl:"α-ритъмът изчезва веднага при отваряне на очите или умствено усилие — заменя се от нисковолтов β (десинхронизация)."},
 {q:"В кой стадий вълните са най-бавни и най-високи?",opts:["REM","N2","N3 (дълбок сън)"],a:2,set:{pre:"n3"},expl:"δ-вълните показват, че огромен брой неврони се разреждат едновременно — кората е „откачена“ от таламуса."},
 {q:"ЕЕГ прилича на будност, но мускулите са напълно отпуснати и очите се движат. Кой стадий е това?",opts:["N1","REM (парадоксален сън)","Епилептичен пристъп"],a:1,set:{pre:"rem"},expl:"Затова за разпознаване на REM са нужни и трите записа: ЕЕГ, движения на очите и мускулен тонус."},
 {q:"Дете „изключва“ за няколко секунди. Какво показва ЕЕГ?",opts:["Плоска линия","Комплекси „шип–вълна“ с честота 3 Hz","δ-вълни"],a:1,set:{pre:"abs"},expl:"Абсансът е генерализиран пристъп от таламокортикалната верига."}];
function viewEeg(main){zAddStg(main,STG_EEGCELL);mkSim(main,{key:"eeg",h2:"ЕЕГ: будност, сън и пристъпи",lead:"Избери състояние и гледай трите записа, по които се разпознават стадиите на съня: мозъчна активност (ЕЕГ), движения на очите (ЕОГ) и мускулен тонус (ЕМГ).",ch:330,speed:1,dtmax:0.004,recdt:0.5,hmax:10,
  sl:[{k:"gain",label:"Усилване на ЕЕГ канала",min:40,max:200,step:10,value:100,unit:"%"},{k:"win",label:"Ширина на прозореца",min:2,max:6,step:1,value:5,unit:"s"}],
  pre:{open:{n:"Будност, отворени очи",info:"<b>β-ритъм</b> (14–30 Hz, ниска амплитуда): невроните работят несинхронно, всеки със своята задача. В ЕОГ се виждат мигания."},
   closed:{n:"Будност, затворени очи",info:"<b>α-ритъм</b> (8–13 Hz, около 50 µV), най-ясен в тилната област. Изчезва при отваряне на очите."},
   n1:{n:"Сън N1 (задрямване)",info:"α-ритъмът се разпада и се заменя от <b>θ-вълни</b> (4–7 Hz). Очите се движат бавно, човек лесно се буди."},
   n2:{n:"Сън N2",info:"На фона на θ се появяват <b>сънни вретена</b> (12–14 Hz, около секунда) и <b>K-комплекси</b>. Това е около половината от съня."},
   n3:{n:"Сън N3 (дълбок, бавновълнов)",info:"<b>δ-вълни</b> (0,5–3,5 Hz, над 75 µV). Най-трудно събуждане; отделя се растежен хормон; налягането и пулсът са най-ниски."},
   rem:{n:"REM сън",info:"ЕЕГ като при будност, <b>бързи движения на очите</b> и пълна <b>мускулна атония</b>. Тук са ярките сънища. Пулсът и дишането са неравномерни."},
   abs:{n:"Абсанс (малък епилептичен пристъп)",info:"Генерализирани комплекси <b>„шип–вълна“ с честота 3 Hz</b> за 3–30 секунди; съзнанието прекъсва, без падане."},
   gm:{n:"Тонично-клоничен пристъп",info:"Високоволтови, високочестотни синхронни разряди по цялата кора; загуба на съзнание, тонично напрежение и после клонични гърчове."}},
  exp:Z_EXP.eeg,init:()=>({ph:[],nz:0,buf:[]}),step:(s,p,dt,t)=>eegStep(s,p,dt,t),rec:(s,p,t)=>[t],calc:p=>EEG_ST[p.pre]||EEG_ST.open,
  stats:(p,R)=>[["Преобладава",EEG_NAME[p.pre]],["δ (< 4 Hz)",R.band[0]+" %"],["θ (4–7 Hz)",R.band[1]+" %"],["α (8–13 Hz)",R.band[2]+" %"],["β (> 13 Hz)",R.band[3]+" %"],["Мускулен тонус",R.emg<0.1?"липсва":R.emg>2?"гърч":R.emg>0.7?"висок":"понижен"]],
  note:(p,R)=>p.pre==="rem"?"<b>Как да го различиш от будност?</b> По ЕМГ: в REM мускулният тонус е нулев (стволът задържа мотоневроните), а очите правят бързи скокове.":p.pre==="n3"||p.pre==="abs"?"<b>Високи бавни вълни = синхронизация.</b> Амплитудата на ЕЕГ не показва колко активни са невроните, а колко <i>едновременно</i> работят.":"Честотата расте с активността на кората, а амплитудата — със синхронизацията. Будната кора е бърза и „тиха“.",
  plots:[{f:(p)=>{const H=[[0,0],[0.15,-1],[0.3,-2],[0.55,-3],[1.1,-3],[1.25,-2],[1.4,-0.5],[1.55,-0.5],[1.7,-2],[2.0,-3],[2.5,-3],[2.7,-2],[2.95,-0.5],[3.25,-0.5],[3.4,-2],[3.9,-2.6],[4.2,-2],[4.4,-0.5],[4.9,-0.5],[5.05,-2],[5.7,-2],[5.9,-0.5],[6.55,-0.5],[6.7,-2],[7.2,-2],[7.35,-0.5],[7.9,-0.5],[8,0]],x=[],y=[];H.forEach((a,i)=>{if(i){x.push(a[0]);y.push(H[i-1][1])}x.push(a[0]);y.push(a[1])});const cur={open:0,closed:0,n1:-1,n2:-2,n3:-3,rem:-0.5}[p.pre];
     return {xmin:0,xmax:8,ymin:-3.4,ymax:0.4,xlabel:"часове сън",ylabel:"0 будност · −0,5 REM · −1…−3 N1…N3",series:[{x,y,color:css("--accent"),width:2}],hlines:cur!=null?[{y:cur,color:css("--accent2"),label:"сега"}]:[]}}},
   {f:(p,R)=>{const x=[],y=[];R.band.forEach((v,i)=>{x.push(i+0.6,i+0.6,i+1.4,i+1.4);y.push(0,v,v,0)});return {xmin:0.2,xmax:4.8,ymin:0,ymax:100,xlabel:"1 = δ · 2 = θ · 3 = α · 4 = β",ylabel:"дял от мощността, %",series:[{x,y,color:css("--accent4"),width:2.4}]}}}],
  legend:`<span><i style="background:var(--accent)"></i>хипнограма на една нощ (цикли ≈ 90 min; дълбокият сън е в началото, REM — към сутринта)</span><span><i style="background:var(--accent4)"></i>спектър на ЕЕГ</span>`,
  draw(g,p,R,t,dt,s){const x0=90,x1=620,W=p.win,ch=[["ЕЕГ",62,0.5,css("--accent")||ZC.blue,"µV"],["ЕОГ (очи)",176,0.42,ZC.grn,""],["ЕМГ (брадичка)",262,0.5,ZC.org,""]];
    g.strokeStyle=css("--grid");g.lineWidth=1;for(let k=0;k<=W;k++){const x=x1-k/W*(x1-x0);g.beginPath();g.moveTo(x,14);g.lineTo(x,300);g.stroke()}
    ch.forEach(([l,y,k,c],ci)=>{Z.T(g,44,y-6,l.split(" ")[0],{fs:11.5,w:700,c});if(l.includes(" "))Z.T(g,44,y+8,l.split(" ").slice(1).join(" "),{fs:9.5,c:css("--muted")});g.strokeStyle=c;g.lineWidth=1.3;g.beginPath();let st=0;const lim=ci===0?56:34;for(const b of s.buf){const x=x1-(t-b[0])/W*(x1-x0);if(x<x0)continue;const yy=y-Z.cl(b[ci+1]*k,-lim,lim);st?g.lineTo(x,yy):g.moveTo(x,yy);st=1}g.stroke()});
    g.strokeStyle=css("--ink");g.lineWidth=1.5;g.beginPath();g.moveTo(x1+6,62);g.lineTo(x1+6,62-25*p.gain/100);g.stroke();Z.T(g,x1+10,40,"50",{fs:9,c:css("--muted")});Z.T(g,x1+10,50,"µV",{fs:9,c:css("--muted")});
    Z.T(g,(x0+x1)/2,316,"1 деление = 1 s · "+EEG_NAME[p.pre],{fs:11,w:700,c:css("--ink")})}})}
{const {S,t,tt,box,ln,ar,cr,pth,RED,BLUE,GOLD,VIO,GRN}=BF._;
 BF.zWaves=()=>{let b="";const W=(y,f,a,c,l,d)=>{let p=[];for(let x=0;x<=230;x+=2)p.push([150+x,y-a*Math.sin(x/230*6.283*f)*(0.8+0.2*Math.sin(x*0.13))]);return t(8,y-3,l,{fs:11.5,w:700,c,a:"start"})+t(8,y+11,d,{fs:9.5,c:"var(--muted)",a:"start"})+pth("M"+p.map(q=>q[0].toFixed(1)+" "+q[1].toFixed(1)).join(" L"),{c,w:1.5})};
  b+=W(22,22,3,RED,"β 14–30 Hz","будност, внимание")+W(58,10,8,BLUE,"α 8–13 Hz","покой, затворени очи")+W(96,5.5,10,GRN,"θ 4–7 Hz","задрямване, N1")+W(140,1.6,17,VIO,"δ < 3,5 Hz","дълбок сън N3")+ln(390,10,390,160,{c:"var(--line)"})+tt(450,60,["честота ↓","амплитуда ↑","=","синхронизация ↑"],{fs:10.5,lh:16,c:"var(--muted)"});return S(520,166,b,"Четирите основни ритъма (1 секунда)")}}
Z_BOOK.eeg={title:"ЕЕГ, сън и будност",adv:"ЕЕГ, ЕОГ и ЕМГ в осем състояния; таламокортикален неврон и произход на ЕЕГ сигнала на клетъчно ниво",
 lead:"Електродите върху главата улавят сумата от синаптичните потенциали на милиони неврони. По ритъма им се разбира дали мозъкът е буден, спи, сънува — или е в пристъп. По Guyton, гл. 60.",
 secs:[{h:"Какво записва ЕЕГ",html:`<p>ЕЕГ не записва акционни потенциали — те са твърде кратки и несинхронни. Записва сумата от <b>постсинаптичните потенциали</b> върху дендритите на пирамидните клетки, които са подредени успоредно и перпендикулярно на повърхността на кората. Сигналът е много слаб (до 200 µV) и е видим само когато <b>много неврони работят едновременно</b>.</p><p>Затова правилото е: колкото по-синхронна е кората, толкова по-високи и бавни са вълните; активната, будна кора дава ниски и бързи вълни (<b>десинхронизация</b>).</p>`},
  {h:"Ритми",fig:BF.zWaves(),html:`<ul><li><b>α</b> (8–13 Hz, ≈ 50 µV): буден, спокоен, със затворени очи; най-изразен тилно. Изисква връзка между кората и таламуса.</li><li><b>β</b> (14–30 Hz, ниска амплитуда): отворени очи, внимание, умствена работа.</li><li><b>θ</b> (4–7 Hz): задрямване; нормален при децата; при възрастни — и при емоционално напрежение.</li><li><b>δ</b> (под 3,5 Hz, висока амплитуда): дълбок сън, кърмачета, тежки органични увреждания. Възниква в кората, когато тя е отделена от активиращите влияния на таламуса.</li></ul>`},
  {h:"Будност: възходяща активираща система",html:`<p>Ретикуларната формация на моста и средния мозък непрекъснато активира кората — пряко и през таламуса. Тя получава сигнали от всички сетива (най-силно от болката и проприоцепцията) и от самата кора (положителна обратна връзка). Невроните ѝ използват ацетилхолин, норадреналин (locus coeruleus), серотонин (ядра на рафето), хистамин и орексин от хипоталамуса. Двустранно увреждане на тази система води до кома.</p>`},
  {h:"Сън",html:`<p><b>Бавновълнов (не-REM) сън</b> — стадии N1 → N2 → N3. Тонусът, налягането, пулсът, дишането и обмяната намаляват с 10–30 %. Това е възстановителният сън.</p><p><b>REM сън</b> (парадоксален) — на всеки около 90 минути, 5–30 минути, общо 20–25 % от съня при възрастни (50 % при новородени). ЕЕГ е като при будност, очите се движат бързо, мускулите са напълно отпуснати (задържане на мотоневроните от ствола), пулсът и дишането са неравномерни, сънищата са ярки и се помнят. Мозъчната обмяна е с до 20 % по-висока.</p><p>Сънят се предизвиква <b>активно</b>: от ядрата на рафето, преоптичната област на хипоталамуса и натрупването на аденозин (кофеинът блокира рецепторите му). Денонощният ритъм се задава от супрахиазматичното ядро и мелатонина. При липса на орексин — нарколепсия.</p>`},
  {h:"Епилепсия",html:`<p>Пристъпът е неконтролирана, прекомерно синхронна активност на част от мозъка или на целия мозък.</p><ul><li><b>Генерализиран тонично-клоничен</b>: внезапна загуба на съзнание, тонична фаза, после клонични гърчове; на ЕЕГ — високоволтови, високочестотни разряди навсякъде. Спира от умора и активно задържане; следва сънливост.</li><li><b>Абсанс</b>: 3–30 секунди „изключване“; комплекси шип–вълна 3 Hz от таламокортикалната система.</li><li><b>Фокални</b>: започват от огнище (белег, тумор) и могат да се разпространят по кората.</li></ul>`},
  {h:"Висши функции накратко",html:`<p><b>Памет</b>: краткосрочната се дължи на временно улесняване на синапсите; дългосрочната — на трайни структурни промени (повече места за освобождаване, повече рецептори, нови шипчета) и изисква синтез на белтъци. <b>Хипокампът</b> е нужен за превръщането на новите факти в трайни спомени; при двустранното му увреждане — антероградна амнезия.</p><p><b>Реч</b>: полето на Вернике (разбиране) и полето на Брока (двигателна програма на говора), обикновено в лявото полукълбо. Префронталната кора — планиране, работна памет, задръжки в поведението.</p>`}],
 key:["ЕЕГ = сума от постсинаптични потенциали на пирамидните клетки, не акционни потенциали.","Синхронизация → високи бавни вълни; активна кора → ниски бързи вълни.","α: затворени очи; β: внимание; θ: задрямване; δ: дълбок сън.","REM: ЕЕГ като будност + бързи движения на очите + мускулна атония; цикли ≈ 90 min.","Будността се поддържа от възходящата ретикуларна активираща система.","Абсанс: шип–вълна 3 Hz; тонично-клоничен: генерализирани високоволтови разряди."]};
Z_TESTS.eeg=[
 {q:"От какво се получава ЕЕГ сигналът?",opts:["От акционните потенциали на аксоните","От сумата на постсинаптичните потенциали в пирамидните клетки","От глията","От ликвора"],a:1,expl:"Те са по-бавни и се сумират, защото дендритите са успоредни."},
 {q:"Кой ритъм е типичен за спокойна будност със затворени очи?",opts:["α","β","θ","δ"],a:0,expl:"8–13 Hz, тилно; блокира се при отваряне на очите."},
 {q:"Какво означават високите бавни δ-вълни?",opts:["Висока активност на кората","Силна синхронизация на невроните","Артефакт","Сънуване"],a:1,expl:"Типични за дълбокия не-REM сън."},
 {q:"В кой стадий на съня има мускулна атония?",opts:["N1","N2","N3","REM"],a:3,expl:"Стволът активно задържа гръбначните мотоневрони."},
 {q:"Колко трае един цикъл на съня?",opts:["Около 20 минути","Около 90 минути","4 часа","Цялата нощ"],a:1,expl:"Към сутринта REM епизодите се удължават, а дълбокият сън намалява."},
 {q:"Какво е характерно за стадий N2?",opts:["δ-вълни","Сънни вретена и K-комплекси","α-ритъм","Бързи движения на очите"],a:1,expl:"Вретената се генерират от таламуса."},
 {q:"Коя структура поддържа будността?",opts:["Малкият мозък","Възходящата ретикуларна активираща система","Базалните ганглии","Хипокампът"],a:1,expl:"Двустранното ѝ увреждане води до кома."},
 {q:"Защо кофеинът държи будни?",opts:["Блокира аденозиновите рецептори","Активира GABA","Блокира орексина","Повишава мелатонина"],a:0,expl:"Аденозинът се натрупва през деня и предизвиква сънливост."},
 {q:"Какво показва ЕЕГ при абсанс?",opts:["Плоска линия","Шип–вълна 3 Hz","α-ритъм","Сънни вретена"],a:1,expl:"Генерализиран пристъп от таламокортикален произход."},
 {q:"Коя структура е нужна за запомнянето на нови факти?",opts:["Хипокамп","Малък мозък","Полето на Брока","Хипофиза"],a:0,expl:"При двустранно увреждане старите спомени остават, но нови не се образуват."}];
